import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useDispatch } from 'react-redux';
import { createArtwork } from '../../services/api';
import Navbar from '../../components/Navbar';

const CreateArtwork = () => {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    price: '',
    category: 'PAINTING',
    image: null,
  });
  const [preview, setPreview] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setFormData(prev => ({
        ...prev,
        image: file
      }));
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreview(reader.result);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const formDataToSend = new FormData();
      formDataToSend.append('title', formData.title);
      formDataToSend.append('description', formData.description);
      formDataToSend.append('price', formData.price);
      formDataToSend.append('category', formData.category);
      if (formData.image) {
        formDataToSend.append('image', formData.image);
      }

      await createArtwork(formDataToSend);
      navigate('/artist/artworks');
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to create artwork. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-cream">
      <Navbar userType="artist" />
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="bg-white rounded-lg shadow-md p-6">
          <h1 className="text-2xl font-bold text-brown mb-6">Create New Artwork</h1>
          
          {error && (
            <div className="bg-red-50 text-red-500 p-4 rounded-lg mb-6">
              {error}
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-6">
            <div>
              <label htmlFor="title" className="block text-sm font-medium text-brown mb-2">
                Title
              </label>
              <input
                type="text"
                id="title"
                name="title"
                value={formData.title}
                onChange={handleChange}
                required
                className="w-full px-4 py-2 border border-brown/20 rounded-lg focus:outline-none focus:ring-2 focus:ring-coral"
                placeholder="Enter artwork title"
              />
            </div>

            <div>
              <label htmlFor="description" className="block text-sm font-medium text-brown mb-2">
                Description
              </label>
              <textarea
                id="description"
                name="description"
                value={formData.description}
                onChange={handleChange}
                required
                rows="4"
                className="w-full px-4 py-2 border border-brown/20 rounded-lg focus:outline-none focus:ring-2 focus:ring-coral"
                placeholder="Describe your artwork"
              />
            </div>

            <div>
              <label htmlFor="price" className="block text-sm font-medium text-brown mb-2">
                Price ($)
              </label>
              <input
                type="number"
                id="price"
                name="price"
                value={formData.price}
                onChange={handleChange}
                required
                min="0"
                step="0.01"
                className="w-full px-4 py-2 border border-brown/20 rounded-lg focus:outline-none focus:ring-2 focus:ring-coral"
                placeholder="Enter price"
              />
            </div>

            <div>
              <label htmlFor="category" className="block text-sm font-medium text-brown mb-2">
                Category
              </label>
              <select
                id="category"
                name="category"
                value={formData.category}
                onChange={handleChange}
                required
                className="w-full px-4 py-2 border border-brown/20 rounded-lg focus:outline-none focus:ring-2 focus:ring-coral"
              >
                <option value="PAINTING">Painting</option>
                <option value="SCULPTURE">Sculpture</option>
                <option value="PHOTOGRAPHY">Photography</option>
                <option value="DIGITAL">Digital Art</option>
                <option value="CRAFT">Craft</option>
                <option value="OTHER">Other</option>
              </select>
            </div>

            <div>
              <label htmlFor="image" className="block text-sm font-medium text-brown mb-2">
                Artwork Image
              </label>
              <input
                type="file"
                id="image"
                name="image"
                onChange={handleImageChange}
                required
                accept="image/*"
                className="w-full px-4 py-2 border border-brown/20 rounded-lg focus:outline-none focus:ring-2 focus:ring-coral"
              />
              {preview && (
                <div className="mt-4">
                  <img
                    src={preview}
                    alt="Preview"
                    className="max-w-full h-64 object-contain rounded-lg"
                  />
                </div>
              )}
            </div>

            <div className="flex justify-end space-x-4">
              <button
                type="button"
                onClick={() => navigate('/artist/artworks')}
                className="px-6 py-2 border border-brown/20 text-brown rounded-lg hover:bg-brown/5 transition-colors"
              >
                Cancel
              </button>
              <button
                type="submit"
                disabled={loading}
                className="px-6 py-2 bg-coral text-white rounded-lg hover:bg-salmon transition-colors disabled:opacity-50"
              >
                {loading ? 'Creating...' : 'Create Artwork'}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default CreateArtwork;
